+	let stats: Value = serde_json::from_str(&observed.unwrap().unwrap()).unwrap();
+	assert_eq!(stats["total_requests"], 1);
+	assert_eq!(stats["completed"], 1);
+	assert_eq!(stats["active"], 0);
